import type { ZodType } from "zod";

/** Fixed clock for golden runs: timestamps in responses are recorded as real values. */
export const GOLDEN_NOW = new Date("2026-11-20T03:00:00.000Z");

const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
/** Better Auth ids and tokens: 32 random alphanumerics. */
const AUTH_ID = /^[A-Za-z0-9]{32}$/;
/** Generated by `newInviteCode` (seeded codes use another shape and stay visible). */
const INVITE = /^LUMA-[0-9A-Z]{5}-[0-9A-Z]{5}$/;
const RANDOM_QUERY = ["state", "code_challenge", "nonce"];

/** Replaces generated values (random ids, tokens, codes, OAuth state) with placeholders. */
export function normalize(value: unknown): unknown {
  if (typeof value === "string") {
    if (UUID.test(value)) return "<uuid>";
    if (AUTH_ID.test(value)) return "<auth-id>";
    if (INVITE.test(value)) return "<invite>";
    if (value.startsWith("https://") && value.includes("?")) {
      const url = new URL(value);
      for (const k of RANDOM_QUERY) {
        if (url.searchParams.has(k)) url.searchParams.set(k, "<random>");
      }
      return url.toString();
    }
    return value;
  }
  if (Array.isArray(value)) return value.map(normalize);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, normalize(v)]));
  }
  return value;
}

/** A cookie keeps its name and attributes; only the generated value is masked. */
export const maskCookie = (cookie: string) => cookie.replace(/^([^=]+)=[^;]*/, "$1=<random>");

async function digest(text: string) {
  const hash = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(text));
  return [...new Uint8Array(hash)].map((b) => b.toString(16).padStart(2, "0")).join("");
}

/** One response as recorded in a golden file: status, headers, cookies, body, then the app's counts. */
export type Recorded = {
  status: number;
  headers: Record<string, unknown>;
  cookies: string[];
  body: unknown;
  d1Queries: number;
  /** Outbound `fetch` calls (Google, OpenRouter). */
  fetches: number;
  r2Ops?: number;
};

/** A JSON response must match its contract: `contract` for 2xx, `errorSchema` otherwise. */
export function checkContract(
  status: number,
  json: unknown,
  errorSchema: ZodType,
  contract?: ZodType,
) {
  const schema = status >= 400 ? errorSchema : contract;
  if (!schema) throw new Error("no contract for this JSON response");
  const parsed = schema.safeParse(json);
  if (!parsed.success) throw new Error(`contract mismatch: ${parsed.error.message}`);
}

/**
 * Turns a response into its golden record. `counts` are spread last, so their key order
 * is the order the app lists them (`d1Queries`, `fetches`, then any app-specific ones).
 */
export async function recordResponse(
  response: Response,
  counts: Pick<Recorded, "d1Queries" | "fetches" | "r2Ops">,
  errorSchema: ZodType,
  contract?: ZodType,
): Promise<Recorded> {
  const headers = Object.fromEntries(
    [...response.headers]
      .filter(([k]) => k !== "set-cookie")
      .map(([k, v]) => [
        k,
        k === "x-request-id" || k === "set-auth-token" ? "<present>" : normalize(v),
      ]),
  );
  const type = response.headers.get("content-type") ?? "";
  const text = await response.text();
  let body: unknown = text;
  if (type.includes("application/json") && text) {
    const json: unknown = JSON.parse(text);
    checkContract(response.status, json, errorSchema, contract);
    body = normalize(json);
  } else if (type.includes("text/html")) body = { sha256: await digest(text), length: text.length };
  return {
    status: response.status,
    headers,
    cookies: response.headers.getSetCookie().map(maskCookie),
    body,
    ...counts,
  };
}

/** Golden JSON: a stable, reviewable diff when behavior changes. */
export const goldenJson = (steps: Record<string, Recorded>) =>
  `${JSON.stringify(steps, null, 2)}\n`;
